// Generated by Cypress Author on 2026-10-25. Fixture clock barrier only.
export function instantMicros(value) {
  const fraction = value.match(/\.(\d+)/)?.[1] ?? '';
  return (
    BigInt(Date.parse(value.replace(/\.\d+/, ''))) * 1000n +
    BigInt(fraction.padEnd(6, '0'))
  );
}

export function progressAfterPublications(read, publications, attempts = 20) {
  if (
    !publications.length ||
    publications.some(
      (at) => typeof at !== 'string' || !Number.isFinite(Date.parse(at)),
    ) ||
    !Number.isInteger(attempts) ||
    attempts < 1 ||
    attempts > 20
  )
    throw new Error(
      'Published fixture timestamps and bounded attempts required',
    );
  // The Activity DTO truncates PostgreSQL microseconds to milliseconds. The
  // next millisecond is a conservative upper bound, not an exact publication.
  const watermark =
    BigInt(Math.max(...publications.map((at) => Date.parse(at))) + 1) * 1000n;
  const poll = (remaining) =>
    read().then((progress) => {
      if (instantMicros(progress.asOf) >= watermark) return progress;
      if (remaining === 1)
        throw new Error(
          'Server clock has not reached the fixture publication barrier',
        );
      // Poll the server clock only. A wrong count at a valid cut must still fail.
      return poll(remaining - 1);
    });
  return poll(attempts);
}
